SELECT CASE WHEN revenue >= 3900 THEN 'HIGH' ELSE 'LOW' END AS revenue_tier, product_id, DATE_TRUNC('WEEK', sale_date) AS week_start, COUNT(*) AS row_count, BIT_OR(units) AS units_bit_or, MAX(revenue) AS max_revenue, RANK() OVER (PARTITION BY CASE WHEN revenue >= 3900 THEN 'HIGH' ELSE 'LOW' END ORDER BY COUNT(*) DESC) AS row_count_rank FROM store_sales GROUP BY revenue_tier, product_id, week_start ORDER BY row_count DESC NULLS LAST;
